// src/pages/Lubricants.jsx
import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import toast from 'react-hot-toast';
import api, { fmtGHS, fmtDate } from '../utils/api';

export default function LubricantsPage() {
  const [stock, setStock] = useState([]);
  const [locations, setLocations] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editing, setEditing] = useState(null);
  const [totalVal, setTotalVal] = useState(0);

  const { register, handleSubmit, reset, watch } = useForm({
    defaultValues: { unit: 'pcs', opening_qty: '', unit_price: '', reorder_level: 0 }
  });

  const watchedQty = watch('opening_qty');
  const watchedPrice = watch('unit_price');

  useEffect(() => {
    const q = parseFloat(watchedQty) || 0;
    const p = parseFloat(watchedPrice) || 0;
    setTotalVal(q * p);
  }, [watchedQty, watchedPrice]);

  const loadData = () => {
    setLoading(true);
    Promise.all([api.get('/inventory/closing-stock/'), api.get('/inventory/locations/')])
      .then(([s, l]) => {
        setStock(s.data.results || s.data);
        setLocations(l.data.results || l.data);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  };

  useEffect(() => { loadData(); }, []);

  const onSubmit = async (data) => {
    setSaving(true);
    try {
      const payload = {
        name: data.name,
        item_type: 'LUBRICANT',
        unit: data.unit,
        description: data.description,
        reorder_level: parseFloat(data.reorder_level || 0),
      };
      if (parseFloat(data.opening_qty) > 0) {
        payload.opening_qty = parseFloat(data.opening_qty);
        payload.unit_price = parseFloat(data.unit_price);
        payload.location_id = data.location_id;
      }
      if (editing) {
        await api.patch(`/inventory/items/${editing}/`, payload);
        toast.success('Lubricant updated successfully.');
      } else {
        await api.post('/inventory/items/', payload);
        toast.success('Lubricant added successfully.');
      }
      reset({ unit: 'pcs', opening_qty: '', unit_price: '', reorder_level: 0, name: '', description: '' });
      setEditing(null);
      setShowForm(false);
      loadData();
    } catch (e) {
      toast.error(e.response?.data?.detail || JSON.stringify(e.response?.data) || 'Failed to save lubricant.');
    } finally {
      setSaving(false);
    }
  };

  const deleteItem = async (id) => {
    if (!window.confirm('Are you sure you want to delete this lubricant?')) return;
    try {
      await api.delete(`/inventory/items/${id}/`);
      toast.success('Lubricant deleted successfully.');
      loadData();
    } catch (e) {
      toast.error('Cannot delete lubricant. It may have related transactions.');
    }
  };

  const startEdit = (s) => {
    setEditing(s.item__id);
    reset({
      name: s.item__name,
      unit: s.item__unit,
      reorder_level: s.item__reorder_level,
      description: s.description || ''
    });
    setShowForm(true);
  };

  const filtered = stock.filter(s => s.item__item_type === 'LUBRICANT' &&
    (s.item__name?.toLowerCase().includes(search.toLowerCase()) ||
     s.item__item_type?.toLowerCase().includes(search.toLowerCase())));

  const totalItems = filtered.length;
  const lowStock = filtered.filter(s => parseFloat(s.closing_qty || 0) <= parseFloat(s.item__reorder_level || 0) && parseFloat(s.closing_qty || 0) > 0).length;
  const outOfStock = filtered.filter(s => parseFloat(s.closing_qty || 0) <= 0).length;
  const totalValue = filtered.reduce((sum, s) => sum + parseFloat(s.closing_value || 0), 0);

  return (
    <div>
      <div className="kpi-grid mb16" style={{ gridTemplateColumns: 'repeat(4,1fr)' }}>
        {[{ label: 'Total Items', val: totalItems, color: 'var(--blue)' },
          { label: 'Low Stock', val: lowStock, color: 'var(--amber)' },
          { label: 'Out of Stock', val: outOfStock, color: 'var(--red)' },
          { label: 'Total Value', val: fmtGHS(totalValue), color: 'var(--green)', fmt: true }]
          .map((k, i) => (
            <div key={i} className="kpi">
              <div className="kpi-label">{k.label}</div>
              <div className="kpi-val" style={{ color: k.color, fontSize: k.fmt ? 16 : 22 }}>{k.val}</div>
            </div>
          ))}
      </div>

      <div className="card">
        <div className="flex items-center justify-between mb16">
          <div className="card-title" style={{ margin: 0 }}>
            <span className="card-title-ic">🧴</span> Lubricant Management
          </div>
          <div className="flex gap8">
            <input type="text" placeholder="Search lubricants…" value={search} onChange={e => setSearch(e.target.value)}
              style={{ width: 220, padding: '7px 10px', fontSize: 12 }} />
            <button className="btn btn-primary btn-sm" onClick={() => { reset({ unit: 'pcs', opening_qty: '', unit_price: '', reorder_level: 0, name: '', description: '' }); setEditing(null); setShowForm(!showForm); }}>
              {showForm ? 'Cancel' : '+ Add Lubricant'}
            </button>
          </div>
        </div>

        {showForm && (
          <div className="mb16 p16" style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 8 }}>
            <h4 style={{ margin: '0 0 12px 0' }}>{editing ? 'Edit Lubricant' : 'Add New Lubricant'}</h4>
            <form onSubmit={handleSubmit(onSubmit)}>
              <div className="fgrid">
                <div className="fg" style={{ gridColumn: 'span 2' }}>
                  <label>Lubricant Name *</label>
                  <input type="text" placeholder="e.g. Engine Oil" {...register('name', { required: true })} />
                </div>
                <div className="fg">
                  <label>Unit</label>
                  <select {...register('unit')}>
                    <option value="pcs">pcs</option>
                    <option value="litres">litres</option>
                    <option value="kg">kg</option>
                  </select>
                </div>
                <div className="fg">
                  <label>Reorder Quantity</label>
                  <input type="number" step="0.01" min="0" {...register('reorder_level')} />
                </div>
                <div className="fg">
                  <label>Description</label>
                  <input type="text" {...register('description')} />
                </div>
                <div className="sec-div" style={{ marginTop: 12 }}>Opening Stock (Optional)</div>
                <div className="fgrid">
                  <div className="fg">
                    <label>Location</label>
                    <select {...register('location_id')}>
                      <option value="">— Select Location —</option>
                      {locations.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
                    </select>
                  </div>
                  <div className="fg">
                    <label>Opening Quantity</label>
                    <input type="number" step="0.01" min="0" placeholder="0" {...register('opening_qty')} />
                  </div>
                  <div className="fg">
                    <label>Unit Price (GH₵)</label>
                    <input type="number" step="0.01" min="0" placeholder="0.00" {...register('unit_price')} />
                  </div>
                  <div className="fg">
                    <label>Total Value (GH₵) — Auto</label>
                    <div className="calc-box">{fmtGHS(totalVal)}</div>
                  </div>
                </div>
                <div className="flex gap8 mt12">
                  <button type="submit" className="btn btn-primary" disabled={saving}>
                    {saving ? '⏳ Saving…' : editing ? '✓ Update Lubricant' : '✓ Save Lubricant'}
                  </button>
                </div>
              </div>
            </form>
          </div>
        )}

        <div className="tbl-wrap">
          <table>
            <thead>
              <tr>
                <th>Lubricant Name</th><th>Type</th><th>Location</th><th>Op. Qty</th><th>Op. Val</th><th>Closing Qty</th><th>Closing Val</th><th>Reorder Qty</th><th>Status</th><th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading && (<tr><td colSpan={10} style={{ textAlign: 'center', padding: 32, color: 'var(--muted)' }}>Loading…</td></tr>)}
              {!loading && filtered.map(s => {
                const opQty = parseFloat(s.opening_qty || 0);
                const opVal = parseFloat(s.opening_value || 0);
                const qty = parseFloat(s.closing_qty || 0);
                const reorder = parseFloat(s.item__reorder_level || 0);
                const value = parseFloat(s.closing_value || 0);
                const isLow = qty <= reorder && qty > 0;
                const isOut = qty <= 0;
                return (
                  <tr key={`${s.item__id}-${s.location__id}`}>
                    <td style={{ fontWeight: 600 }}><div style={{ fontSize: 10, color: 'var(--muted)', marginBottom: 2 }}>{`ITM-${s.item__id.toString().padStart(4, '0')}`}</div>{s.item__name}</td>
                    <td><span className="badge b-blue">{s.item__item_type}</span></td>
                    <td>{s.location__name || '—'}</td>
                    <td className="mono" style={{ color: 'var(--muted)' }}>{opQty.toLocaleString()}</td>
                    <td className="ced" style={{ color: 'var(--muted)' }}>{fmtGHS(opVal)}</td>
                    <td className="mono" style={{ fontWeight: 700, color: isOut ? 'var(--red)' : isLow ? '#b45309' : 'var(--text)' }}>{qty.toLocaleString()}</td>
                    <td className="ced" style={{ fontWeight: 600 }}>{fmtGHS(value)}</td>
                    <td style={{ color: 'var(--muted)', fontSize: 11 }}>{reorder.toLocaleString()}</td>
                    <td>{isOut && <span className="badge b-red">Out of Stock</span>}{isLow && !isOut && <span className="badge b-amber">Low Stock</span>}{!isLow && !isOut && <span className="badge b-green">OK</span>}</td>
                    <td>
                      <div className="flex gap4">
                        <button className="btn btn-ghost btn-xs" onClick={() => startEdit(s)}>Edit</button>
                        <button className="btn btn-danger btn-xs" onClick={() => deleteItem(s.item__id)}>Del</button>
                      </div>
                    </td>
                  </tr>
                );
              })}
              {!loading && filtered.length === 0 && (<tr><td colSpan={10} style={{ textAlign: 'center', color: 'var(--muted)', padding: 32 }}>No lubricants found</td></tr>)}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
